    private LocalDate deferredUntil;

    /** How many proofs it has: raised by one at a time. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The number of the claim it was split from; none when it was not split off another. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The user whose editor is open on it, locking it for every other user; none while unlocked. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Its status log: one line per status it has had, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    /** Raise its proofs count by one. */
    public void addProof() {
        proofs++;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    public List<StatusChange> getStatusLog() {
        return List.copyOf(statusLog);
    }

    /** Add a line to its status log, for the status it has now. */
    public void logStatus(String by, LocalDate on, BigDecimal due) {
        statusLog.add(new StatusChange(status, by, on, due));
    }
}
     *  it bound (none while unbound, or when that was n/a), and the number a correction corrects (none
     *  otherwise), its status log, oldest first, and the date it is deferred until (none when never deferred), its proofs count,
     *  and the user whose editor is open on it (none while unlocked). */
    public record ClaimView(long id, long personId, String amount, String date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, String corrects, String dueBy, List<StatusLine> statusLog, String deferredUntil,
            int proofs, String splitFrom, String lockedBy) {

        static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate().toString(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getDueBy().toString(),
                    claim.getStatusLog().stream().map(StatusLine::of).toList(),
                    claim.getDeferredUntil() == null ? null : claim.getDeferredUntil().toString(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy());
        }
    }

  /** Its status log: one line per status it has had, oldest first. */
  statusLog: StatusLine[];
  /** The date it was deferred until (YYYY-MM-DD); null when never deferred. It is deferred only while
   *  OPEN and the sheet's today is before it (see `Claims.deferred`). */
  deferredUntil: string | null;
  /** How many proofs it has. One whose due is above the proof threshold in force on its date cannot be
   *  settled or approved with none. */
  proofs: number;
  /** The number of the claim it was split from; null when it was not split off another. */
  splitFrom: string | null;
  /** The user whose editor is open on it, locking it for every other user until they save or cancel it,
   *  or the sheet's today changes; null while unlocked. */
  lockedBy: string | null;
}

