    try {
      const err = await this.periods.add({ name: this.name(), from: this.from(), to: this.to() });
      if (err) this.error.set(err);
      else {
        this.name.set('');
        this.from.set('');
        this.to.set('');
      }
    } finally {
      this.saving.set(false);
    }
